import os
import torch


class Config:
    # --- General Configuration ---
    PROJECT_NAME = "Tumor_Detection_Stacking_Ensemble"
    SEED = 42
    DEBUG = False  # Set to True for fast debugging runs with subsets

    # --- Paths ---
    # Input directories (Read-Only)
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files (Generated by previous steps)
    TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for this specific idea (Read/Write)
    WORKING_DIR = "./working/idea_optimized"

    # Submission paths
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --- Data Processing ---
    # The task requires predicting the center 32x32px region.
    # We use a 64x64px crop to provide context (16px buffer around the 32px ROI).
    CROP_SIZE = 64
    IMG_SIZE = (64, 64)

    # --- Model Architecture ---
    # Single strong model as per Lesson 00015 (Ensembling disparate performers degrades accuracy)
    MODEL_ARCHS = ["convnext_tiny"]

    # --- Training Hyperparameters ---
    NUM_FOLDS = 5
    EPOCHS = 20  # Optimized to 20 as per Lesson 00014

    # A100 40GB allows for large batch sizes with 64x64 images
    BATCH_SIZE = 512

    LEARNING_RATE = 2e-4
    WEIGHT_DECAY = 1e-4

    # Scheduler settings (Cosine Annealing)
    T_MAX = EPOCHS
    MIN_LR = 1e-6

    # --- Compute ---
    NUM_WORKERS = 12
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # --- Inference ---
    # Test Time Augmentation: Original + Horizontal + Vertical + Both
    TTA_STEPS = 4

    @classmethod
    def setup(cls):
        """Ensures necessary directories exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Run setup on import to ensure directories exist
Config.setup()
